const API_ORIGIN = 'https://api.tokenlab.sh';
// Accept relative (/v1/tasks/..) and same-origin absolute poll URLs; never send the key to another host.
// Plain string checks: the Code node sandbox may not expose the URL global.
function resolvePollUrl(pollUrl) {
  const value = String(pollUrl).trim();
  if (value.startsWith(API_ORIGIN + '/')) return value;
  if (value.startsWith('/') && !value.startsWith('//')) return API_ORIGIN + value;
  throw new Error(`Refusing to poll a non-TokenLab URL: ${value}`);
}
const task = $json;
const taskId = task.id ?? task.task_id;
if (!taskId) throw new Error('TokenLab did not return a task id');
const pollUrl = resolvePollUrl(task.poll_url ?? `/v1/tasks/${encodeURIComponent(taskId)}`);
return [{ json: { ...task, task_id: taskId, poll_url: pollUrl, terminal: false } }];

